.parallax-text-wrap { 
  height: 200vh; overflow-x: hidden; position: relative; padding-top: 50vh;
}
.row-text {
  font-size: 80px; font-weight: 900; white-space: nowrap;
  color: rgba(255,255,255,0.05); text-transform: uppercase;
  font-family: sans-serif; line-height: 1; transition: transform 0.1s linear;
}
.row-2 { color: rgba(168,85,247,0.1); -webkit-text-stroke: 1px rgba(168,85,247,0.3); }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'parallax-text-wrap';

const row1 = document.createElement('div');
row1.className = 'row-text';
row1.innerText = 'ULTRA MAX PREMIUM PRO SUPER ANIMATION MOTIONZYNC ';

const row2 = document.createElement('div');
row2.className = 'row-text row-2';
row2.innerText = ' MOTIONZYNC ULTRA MAX PREMIUM PRO SUPER ANIMATION';

wrap.appendChild(row1);
wrap.appendChild(row2);
c.appendChild(wrap);

c.addEventListener('scroll', () => {
  const scrolled = c.scrollTop;
  row1.style.transform = `translateX(-${scrolled * 0.8}px)`;
  row2.style.transform = `translateX(${scrolled * 0.8 - 500}px)`; // જમણી બાજુ જશે
});
